"""Regenerate this isolated preview from the live copy; never writes production (19 Nov 2026)."""
from pathlib import Path
import re,json
root=Path(__file__).resolve().parents[3]
s=(root/'src/pages/index.html').read_text()
s=re.sub(r'<script[^>]*src=[^>]*>.*?</script>','',s,flags=re.S)
s=re.sub(r'<script type="application/ld\+json">.*?</script>','',s,flags=re.S)
s=re.sub(r'<meta name="robots"[^>]*>','<meta name="robots" content="noindex,nofollow">',s)
s=re.sub(r'<link[^>]*(?:rel="canonical"|rel="preconnect"|rel="dns-prefetch")[^>]*>','',s)
s=re.sub(r'<meta[^>]*(?:property="og:|name="twitter:)[^>]*>','',s)
shots=json.loads(re.search(r'const SHOTS = (\[.*?\]);',s,re.S).group(1))
names=['ai-estimate-drafts','your-cash-flow-at-a-glance','manage-invoices-easily','flexible-payment-splits','rebill-expense-markups','understand-your-cash-flow','manage-your-clients','speed-up-invoicing','track-billable-hours','ai-business-logos']
for shot,name in zip(shots,names): s=s.replace(shot['b64'],f'../assets/screens/{name}.webp')
s=s.replace(' loading="lazy"','')
# Keep real product interactions while dropping every analytics and acquisition handler.
s=s[:s.index('    // GA4 Custom Event Tracking')]+ '\n  </script>\n</body>\n</html>'
hero=re.search(r'(<section class="hero-section">\s*<div class="container">)(.*?)(\n      </div>\n    </section>)',s,re.S)
visual='''<div class="split-product" aria-label="InvoiceSnap app screens"><img class="split-screen split-screen-back" src="../assets/screens/your-cash-flow-at-a-glance.webp" alt="Your Cash Flow at a Glance" width="540" height="1170"><img class="split-screen split-screen-front" src="../assets/screens/manage-invoices-easily.webp" alt="Manage Invoices Easily" width="540" height="1170"></div>'''
s=s[:hero.start()]+hero.group(1)+'<div class="split-copy">'+hero.group(2)+'</div>'+visual+hero.group(3)+s[hero.end():]
# Registry 1831 uses 200ms menu, 150ms links and no entrance motion; keep those timings.
